```yaml
# File: cloudformation/notification-stack.yaml
# AWS-native. State managed by AWS as a Stack. Automatic rollback on failure.
AWSTemplateFormatVersion: "2010-09-09"
Description: Notification stack for National Bank of India payments

Parameters:                               # like Terraform variables
  Environment:
    Type: String
    AllowedValues: [staging, production]

Conditions:                               # declarative conditionals
  IsProd: !Equals [!Ref Environment, production]

Resources:
  NotificationQueue:
    Type: AWS::SQS::Queue
    Properties:
      QueueName: !Sub "nbi-notifications-${Environment}"
      # Longer retention in prod via a Condition.
      MessageRetentionPeriod: !If [IsProd, 1209600, 345600]
      KmsMasterKeyId: alias/aws/sqs       # encryption at rest

  ArchiveBucket:
    Type: AWS::S3::Bucket
    Properties:
      BucketName: !Sub "nbi-notification-archive-${Environment}"
      BucketEncryption:
        ServerSideEncryptionConfiguration:
          - ServerSideEncryptionByDefault:
              SSEAlgorithm: aws:kms
      PublicAccessBlockConfiguration:      # never public — bank data
        BlockPublicAcls: true
        BlockPublicPolicy: true
        IgnorePublicAcls: true
        RestrictPublicBuckets: true

Outputs:                                   # consumed by the app
  QueueUrl:
    Value: !Ref NotificationQueue
  ArchiveBucketName:
    Value: !Ref ArchiveBucket
```

```hcl
# File: terraform/main.tf
# Multi-cloud HCL. State is YOURS to store/lock. No auto-rollback.
variable "environment" {
  type = string
}

resource "aws_sqs_queue" "notifications" {
  name                      = "nbi-notifications-${var.environment}"
  # HCL ternary instead of a YAML Condition.
  message_retention_seconds = var.environment == "production" ? 1209600 : 345600
  kms_master_key_id         = "alias/aws/sqs"
}

resource "aws_s3_bucket" "archive" {
  bucket = "nbi-notification-archive-${var.environment}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "archive" {
  bucket = aws_s3_bucket.archive.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" }
  }
}

resource "aws_s3_bucket_public_access_block" "archive" {
  bucket                  = aws_s3_bucket.archive.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Terraform's edge: same tool can ALSO manage non-AWS providers.
# resource "pagerduty_service" "payments_oncall" { ... }   # impossible in CFN
```

