// ─── File: src/main/java/com/bank/payments/config/NotificationQueueConfig.java ───
package com.bank.payments.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import software.amazon.awssdk.services.sqs.SqsClient;

// The app reads the queue URL from an output. It does NOT know or care
// whether CloudFormation or Terraform created the queue — proof the
// choice of tool is an infrastructure concern, not an application one.
@Configuration
public class NotificationQueueConfig {

    @Value("${NOTIFICATION_QUEUE_URL}")   // from CFN Output OR TF output
    private String queueUrl;

    @Bean
    public SqsClient sqsClient() {
        return SqsClient.create();
    }

    @Bean
    public String notificationQueueUrl() {
        return queueUrl;
    }
}
